<?php

declare(strict_types=1);

use Karoor\Core\Helpers;

$allowedViews = ['products', 'stock', 'movements', 'categories', 'warehouses', 'adjustments', 'transfers'];
$inventoryView = is_string($_GET['view'] ?? null) && in_array($_GET['view'], $allowedViews, true) ? $_GET['view'] : 'products';
$viewLabels = ['products'=>'Products','stock'=>'Warehouse Stock','movements'=>'Stock Movements','categories'=>'Categories','warehouses'=>'Warehouses','adjustments'=>'Adjustments','transfers'=>'Transfers'];
$pageTitle = $viewLabels[$inventoryView];
$pageDescription = 'Traceable inventory controls across products, warehouses, movements, and transfers.';
$breadcrumbs = [['label'=>'Inventory','url'=>'/inventory'], $pageTitle];
$companyId = (int) $currentUser['company_id'];
$warehouses = $database->fetchAll('SELECT id, code, name FROM warehouses WHERE company_id=:company AND is_active=1 AND deleted_at IS NULL ORDER BY name', ['company'=>$companyId]);
$categories = $database->fetchAll('SELECT id, name FROM categories WHERE company_id=:company AND deleted_at IS NULL ORDER BY sort_order,name', ['company'=>$companyId]);
$products = $database->fetchAll('SELECT id, sku, name, purchase_price FROM products WHERE company_id=:company AND is_active=1 AND deleted_at IS NULL ORDER BY name LIMIT 1000', ['company'=>$companyId]);
$units = $database->fetchAll('SELECT id, name, short_name FROM units WHERE company_id=:company AND is_active=1 AND deleted_at IS NULL ORDER BY name', ['company'=>$companyId]);
$brands = $database->fetchAll('SELECT id, name FROM brands WHERE company_id=:company AND is_active=1 AND deleted_at IS NULL ORDER BY name', ['company'=>$companyId]);
$taxes = $database->fetchAll('SELECT id, name, rate FROM taxes WHERE company_id=:company AND is_active=1 AND deleted_at IS NULL ORDER BY name', ['company'=>$companyId]);
$canCreate = match ($inventoryView) { 'products','categories','warehouses' => $auth->can('inventory.create'), 'adjustments'=>$auth->can('inventory.adjust'), 'transfers'=>$auth->can('inventory.transfer'), default=>false };
$pageActions = static function () use ($canCreate, $inventoryView, $viewLabels): void { if ($canCreate) echo '<button class="btn btn-primary" type="button" data-bs-toggle="modal" data-bs-target="#inventoryCreateModal"><i class="fa-solid fa-plus" aria-hidden="true"></i> New ' . Helpers::escape(rtrim(strtolower($viewLabels[$inventoryView]), 's')) . '</button>'; };

$tables = [
 'products'=>[['sku','SKU','text'],['name','Product','text'],['category_name','Category','text'],['selling_price','Selling price','currency'],['total_stock','Total stock','number'],['is_active','Active','boolean']],
 'stock'=>[['sku','SKU','text'],['product_name','Product','text'],['warehouse_name','Warehouse','text'],['quantity','On hand','number'],['reserved_quantity','Reserved','number'],['available_quantity','Available','number'],['average_cost','Average cost','currency']],
 'movements'=>[['movement_at','Date','datetime'],['product_name','Product','text'],['warehouse_name','Warehouse','text'],['movement_type','Type','status'],['quantity','Quantity','number'],['quantity_before','Before','number'],['quantity_after','After','number'],['reference_type','Reference','text']],
 'categories'=>[['name','Category','text'],['parent_name','Parent','text'],['product_count','Products','number'],['sort_order','Order','number'],['is_active','Active','boolean']],
 'warehouses'=>[['code','Code','text'],['name','Warehouse','text'],['branch_name','Branch','text'],['product_count','Products','number'],['stock_value','Stock value','currency'],['is_default','Default','boolean'],['is_active','Active','boolean']],
 'adjustments'=>[['adjustment_number','Adjustment','text'],['adjustment_date','Date','datetime'],['warehouse_name','Warehouse','text'],['adjustment_type','Type','status'],['reason','Reason','text'],['status','Status','status'],['id','Actions','actions']],
 'transfers'=>[['transfer_number','Transfer','text'],['transfer_date','Date','datetime'],['from_warehouse','From','text'],['to_warehouse','To','text'],['status','Status','status'],['requested_by_name','Requested by','text'],['id','Actions','actions']],
];
require __DIR__ . '/../layouts/header.php';
?>

<nav class="nav nav-pills flex-nowrap overflow-auto mb-4" aria-label="Inventory sections"><?php foreach ($viewLabels as $key=>$label): ?><a class="nav-link<?= $key===$inventoryView?' active':'' ?>" href="<?= Helpers::escape(Helpers::appPath($config, '/inventory?view='.$key)) ?>"><?= Helpers::escape($label) ?></a><?php endforeach; ?></nav>

<section class="surface-card">
 <div class="card-header-row flex-wrap gap-3"><div><h2><?= Helpers::escape($pageTitle) ?></h2><p>Live records from the inventory ledger.</p></div><?php if (in_array($inventoryView,['products','stock','movements'],true)): ?><div class="input-group" style="max-width:340px"><span class="input-group-text"><i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i></span><label class="visually-hidden" for="inventorySearch">Search inventory</label><input class="form-control" id="inventorySearch" data-table-search="inventoryTable" type="search" placeholder="Search records…"></div><?php endif; ?></div>
 <?php if (in_array($inventoryView,['products','stock','movements'],true)): ?><form class="card-body-pad border-bottom row g-2 align-items-end" data-table-filters="inventoryTable"><div class="col-12 col-md-5"><label class="form-label" for="inventoryWarehouseFilter">Warehouse</label><select class="form-select" id="inventoryWarehouseFilter" name="warehouse_id"><option value="">All warehouses</option><?php foreach($warehouses as $warehouse):?><option value="<?= (int)$warehouse['id'] ?>"><?= Helpers::escape((string)$warehouse['name']) ?></option><?php endforeach;?></select></div><?php if($inventoryView==='products'):?><div class="col-12 col-md-4"><label class="form-label" for="inventoryCategoryFilter">Category</label><select class="form-select" id="inventoryCategoryFilter" name="category_id"><option value="">All categories</option><?php foreach($categories as $category):?><option value="<?= (int)$category['id'] ?>"><?= Helpers::escape((string)$category['name']) ?></option><?php endforeach;?></select></div><?php endif;?><div class="col-12 col-md-3 d-flex gap-2"><button class="btn btn-outline-primary" type="submit">Apply</button><button class="btn btn-outline-secondary" type="reset">Reset</button></div></form><?php endif; ?>
 <div class="table-responsive"><table class="table align-middle mb-0" id="inventoryTable" data-api-table data-endpoint="inventory/<?= Helpers::escape($inventoryView) ?>"><thead><tr><?php foreach($tables[$inventoryView] as [$field,$label,$format]):?><th data-field="<?= Helpers::escape($field) ?>"<?= $format!=='text'?' data-format="'.Helpers::escape($format).'"':'' ?>><?= Helpers::escape($label) ?></th><?php endforeach;?></tr></thead><tbody></tbody></table></div>
 <?php if(in_array($inventoryView,['products','stock','movements'],true)):?><div class="card-body-pad d-flex justify-content-end"><div class="btn-group"><button class="btn btn-outline-secondary" type="button" data-table-page="inventoryTable" data-page="previous">Previous</button><button class="btn btn-outline-secondary" type="button" data-table-page="inventoryTable" data-page="next">Next</button></div></div><?php endif;?>
</section>

<?php if($canCreate):?><div class="modal fade" id="inventoryCreateModal" tabindex="-1" aria-labelledby="inventoryCreateTitle" aria-hidden="true"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content">
<?php if($inventoryView==='products'):?><form data-api-form data-endpoint="inventory/products" data-method="POST" data-encoding="multipart" data-success-redirect="<?= Helpers::escape(Helpers::appPath($config,'/inventory?view=products')) ?>"><div class="modal-header"><h2 class="modal-title fs-5" id="inventoryCreateTitle">Add product</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><div class="row g-3"><div class="col-md-6"><label class="form-label" for="productName">Product name</label><input class="form-control" id="productName" name="name" required maxlength="190"></div><div class="col-md-3"><label class="form-label" for="productSku">SKU</label><input class="form-control" id="productSku" name="sku" required maxlength="100"></div><div class="col-md-3"><label class="form-label" for="productBarcode">Barcode</label><input class="form-control" id="productBarcode" name="barcode" maxlength="100"></div><div class="col-md-4"><label class="form-label" for="productCategory">Category</label><select class="form-select" id="productCategory" name="category_id"><option value="">Uncategorized</option><?php foreach($categories as $category):?><option value="<?= (int)$category['id'] ?>"><?= Helpers::escape((string)$category['name']) ?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label" for="productUnit">Unit</label><select class="form-select" id="productUnit" name="unit_id" required><option value="">Select unit</option><?php foreach($units as $unit):?><option value="<?= (int)$unit['id'] ?>"><?= Helpers::escape((string)$unit['name']) ?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label" for="productBrand">Brand</label><select class="form-select" id="productBrand" name="brand_id"><option value="">No brand</option><?php foreach($brands as $brand):?><option value="<?= (int)$brand['id'] ?>"><?= Helpers::escape((string)$brand['name']) ?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label" for="purchasePrice">Purchase price</label><input class="form-control" id="purchasePrice" name="purchase_price" type="number" min="0" step="0.01" required></div><div class="col-md-3"><label class="form-label" for="sellingPrice">Selling price</label><input class="form-control" id="sellingPrice" name="selling_price" type="number" min="0" step="0.01" required></div><div class="col-md-3"><label class="form-label" for="wholesalePrice">Wholesale price</label><input class="form-control" id="wholesalePrice" name="wholesale_price" type="number" min="0" step="0.01"></div><div class="col-md-3"><label class="form-label" for="minimumStock">Minimum stock</label><input class="form-control" id="minimumStock" name="minimum_stock" type="number" min="0" step="0.0001" value="0"></div><div class="col-md-4"><label class="form-label" for="productTax">Tax</label><select class="form-select" id="productTax" name="tax_id"><option value="">No tax</option><?php foreach($taxes as $tax):?><option value="<?= (int)$tax['id'] ?>"><?= Helpers::escape((string)$tax['name']) ?> (<?= Helpers::escape((string)$tax['rate']) ?>%)</option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label" for="productType">Type</label><select class="form-select" id="productType" name="product_type"><option value="STOCK">Stock item</option><option value="SERVICE">Service</option></select></div><div class="col-md-4"><label class="form-label" for="productImage">Image</label><input class="form-control" id="productImage" name="image" type="file" accept="image/jpeg,image/png,image/webp,image/gif"></div></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary" type="submit">Save product</button></div></form>
<?php elseif($inventoryView==='categories'):?><form data-api-form data-endpoint="inventory/categories" data-method="POST" data-success-redirect="<?= Helpers::escape(Helpers::appPath($config,'/inventory?view=categories')) ?>"><div class="modal-header"><h2 class="modal-title fs-5" id="inventoryCreateTitle">Add category</h2><button class="btn-close" type="button" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><label class="form-label" for="categoryName">Name</label><input class="form-control" id="categoryName" name="name" required maxlength="150"><label class="form-label mt-3" for="parentCategory">Parent category</label><select class="form-select" id="parentCategory" name="parent_id"><option value="">Top level</option><?php foreach($categories as $category):?><option value="<?= (int)$category['id'] ?>"><?= Helpers::escape((string)$category['name']) ?></option><?php endforeach;?></select><label class="form-label mt-3" for="categoryDescription">Description</label><textarea class="form-control" id="categoryDescription" name="description" rows="3"></textarea></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary" type="submit">Save category</button></div></form>
<?php elseif($inventoryView==='warehouses'):?><form data-api-form data-endpoint="inventory/warehouses" data-method="POST" data-success-redirect="<?= Helpers::escape(Helpers::appPath($config,'/inventory?view=warehouses')) ?>"><div class="modal-header"><h2 class="modal-title fs-5" id="inventoryCreateTitle">Add warehouse</h2><button class="btn-close" type="button" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><div class="row g-3"><div class="col-md-4"><label class="form-label" for="warehouseCode">Code</label><input class="form-control" id="warehouseCode" name="code" required maxlength="30"></div><div class="col-md-8"><label class="form-label" for="warehouseName">Name</label><input class="form-control" id="warehouseName" name="name" required maxlength="150"></div><div class="col-md-6"><label class="form-label" for="warehousePhone">Phone</label><input class="form-control" id="warehousePhone" name="phone" maxlength="50"></div><div class="col-md-6"><label class="form-label" for="warehouseEmail">Email</label><input class="form-control" id="warehouseEmail" name="email" type="email"></div><div class="col-12"><label class="form-label" for="warehouseAddress">Address</label><input class="form-control" id="warehouseAddress" name="address" maxlength="255"></div></div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary" type="submit">Save warehouse</button></div></form>
<?php elseif(in_array($inventoryView,['adjustments','transfers'],true)):?><form id="inventoryMovementForm" data-mode="<?= Helpers::escape($inventoryView) ?>"><div class="modal-header"><h2 class="modal-title fs-5" id="inventoryCreateTitle">New <?= Helpers::escape(rtrim($viewLabels[$inventoryView],'s')) ?></h2><button class="btn-close" type="button" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><div class="row g-3"><?php if($inventoryView==='adjustments'):?><div class="col-md-6"><label class="form-label" for="movementWarehouse">Warehouse</label><select class="form-select" id="movementWarehouse" name="warehouse_id" required><option value="">Select warehouse</option><?php foreach($warehouses as $warehouse):?><option value="<?= (int)$warehouse['id'] ?>"><?= Helpers::escape((string)$warehouse['name']) ?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label" for="adjustmentType">Direction</label><select class="form-select" id="adjustmentType" name="adjustment_type"><option value="IN">Increase stock</option><option value="OUT">Decrease stock</option></select></div><div class="col-12"><label class="form-label" for="adjustmentReason">Reason</label><input class="form-control" id="adjustmentReason" name="reason" required maxlength="255"></div><?php else:?><div class="col-md-6"><label class="form-label" for="fromWarehouse">From warehouse</label><select class="form-select" id="fromWarehouse" name="from_warehouse_id" required><option value="">Select</option><?php foreach($warehouses as $warehouse):?><option value="<?= (int)$warehouse['id'] ?>"><?= Helpers::escape((string)$warehouse['name']) ?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label" for="toWarehouse">To warehouse</label><select class="form-select" id="toWarehouse" name="to_warehouse_id" required><option value="">Select</option><?php foreach($warehouses as $warehouse):?><option value="<?= (int)$warehouse['id'] ?>"><?= Helpers::escape((string)$warehouse['name']) ?></option><?php endforeach;?></select></div><?php endif;?><div class="col-md-7"><label class="form-label" for="movementProduct">Product</label><select class="form-select" id="movementProduct" required><option value="">Select product</option><?php foreach($products as $product):?><option value="<?= (int)$product['id'] ?>" data-cost="<?= Helpers::escape((string)$product['purchase_price']) ?>"><?= Helpers::escape((string)$product['name']) ?> (<?= Helpers::escape((string)$product['sku']) ?>)</option><?php endforeach;?></select></div><div class="col-md-5"><label class="form-label" for="movementQuantity">Quantity</label><input class="form-control" id="movementQuantity" type="number" min="0.0001" step="0.0001" required></div><?php if($inventoryView==='transfers'):?><div class="col-12"><label class="form-label" for="transferNotes">Notes</label><textarea class="form-control" id="transferNotes" name="notes" rows="3"></textarea></div><?php endif;?></div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary" type="submit">Save</button></div></form><?php endif;?>
</div></div></div><?php endif;?>

